import { atom } from "recoil"
import type { Bill, FilterOptions } from "../types/types"

export const Lang = atom<Object>({
  key: "lang",
  default: {},
})

export const BillsState = atom<Bill[]>({
  key: "bills",
  default: [],
})

export const LoadingState = atom<boolean>({
  key: "loading",
  default: false,
})

export const FilterState = atom<FilterOptions>({
  key: "filter",
  default: {
    status: "unpaid",
    dateRange: [null, null],
    minAmount: null,
    maxAmount: null,
    clientName: "",
  },
})

export const SelectedBillState = atom<Bill | null>({
  key: "selectedBill",
  default: null,
})
