  const isSettingsTab = activeTab === 'INDSTILLINGER';
  const isExpensesTab = activeTab === 'UDGIFTER';

  const getCompanyLogoUrl = () => {
    if (businessData.companyLogo && businessData.companyLogo.trim() !== "") {
      return businessData.companyLogo
    }
    return "/placeholder.svg?height=60&width=60"
  }

