"use client"

import { useEffect, useRef, useMemo, useState, useCallback } from "react"
import { Box, Text } from "@mantine/core"
import classes from "./lineChart.module.css"

interface DayData {
  dayName: string
  dayNumber: string
  fullLabel: string
  date: Date
}

interface ChartData {
  labels?: string[]
  values?: number[]
}

interface LineChartProps {
  chartData?: ChartData
  title?: string
}

interface Point {
  x: number
  y: number
  value: number
  label: string
}

// Generate last 30 days with day names and dates
const useLast30Days = (): DayData[] => {
  return useMemo(() => {
    const result: DayData[] = []
    const today = new Date()
    today.setHours(0, 0, 0, 0)
    const dayNames = ['SØN', 'MAN', 'TIR', 'ONS', 'TOR', 'FRE', 'LØR']
    
    for (let i = 29; i >= 0; i--) {
      const date = new Date(today)
      date.setDate(date.getDate() - i)
      const dayName = dayNames[date.getDay()]
      const dayNumber = date.getDate()
      
      result.push({
        dayName,
        dayNumber: dayNumber.toString(),
        fullLabel: `${dayName} ${dayNumber}`,
        date
      })
    }
    
    return result
  }, [])
}

// Format number to K/M format, handling negative numbers
const formatNumber = (num: number): string => {
  const absNum = Math.abs(num)
  let formatted: string
  
  if (absNum >= 1000000) {
    formatted = `${(absNum / 1000000).toFixed(1)}M`
  } else if (absNum >= 1000) {
    formatted = `${(absNum / 1000).toFixed(0)}K`
  } else {
    formatted = absNum.toString()
  }
  
  return num < 0 ? `-${formatted}` : formatted
}

export const LineChart = ({ chartData, title = "OMSÆTNING OVERSIGT" }: LineChartProps) => {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const containerRef = useRef<HTMLDivElement>(null)
  const [points, setPoints] = useState<Point[]>([])
  const days = useLast30Days()
  
  // Generate or use provided data
  const data = useMemo(() => {
    return chartData?.values || Array(30).fill(0).map(() => {
      const base = 50000 + Math.random() * 150000
      return Math.round(base / 1000) * 1000
    })
  }, [chartData?.values])

  // Draw chart
  const drawChart = useCallback(() => {
    const canvas = canvasRef.current
    const container = containerRef.current
    if (!canvas || !container) return
    
    const ctx = canvas.getContext('2d')
    if (!ctx) return

    // Set canvas dimensions
    const dpr = window.devicePixelRatio || 1
    const rect = container.getBoundingClientRect()
    
    canvas.width = rect.width * dpr
    canvas.height = rect.height * dpr
    canvas.style.width = `${rect.width}px`
    canvas.style.height = `${rect.height}px`
    
    ctx.scale(dpr, dpr)
    
    // Chart dimensions
    const padding = { top: 10, right: 20, bottom: 40, left: 50 }
    const chartWidth = rect.width - padding.left - padding.right
    const chartHeight = rect.height - padding.top - padding.bottom
    
    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height)
    
    // Skip if no data
    if (data.length === 0) return
    
    // Find min and max values for scaling (with some headroom)
    const minValue = Math.min(0, ...data) * 1.1  // Ensure we include 0 as minimum
    const maxValue = Math.max(0, ...data) * 1.1  // Ensure we include 0 as maximum
    const valueRange = maxValue - minValue
    
    // Calculate points
    const calculatedPoints: Point[] = []
    for (let i = 0; i < data.length; i++) {
      const x = padding.left + (chartWidth / (data.length - 1)) * i
      // Calculate Y position based on value range, accounting for negative values
      const y = padding.top + chartHeight - ((data[i] - minValue) / valueRange) * chartHeight
      
      calculatedPoints.push({
        x,
        y,
        value: data[i],
        label: days[i] ? `${days[i].dayName} ${days[i].dayNumber}` : ''
      })
    }
    setPoints(calculatedPoints)
    
    // Draw Y-axis grid lines and labels
    const numHorizontalLines = 4
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.05)'
    ctx.lineWidth = 1
    
    // Draw zero line first
    const zeroY = minValue < 0 && maxValue > 0 
      ? padding.top + chartHeight * (1 - (-minValue) / valueRange)
      : null
    
    if (zeroY !== null) {
      ctx.beginPath()
      ctx.setLineDash([2, 2])
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.2)'
      ctx.moveTo(padding.left, zeroY)
      ctx.lineTo(padding.left + chartWidth, zeroY)
      ctx.stroke()
    }
    
    // Draw grid lines and labels
    for (let i = 0; i <= numHorizontalLines; i++) {
      const y = padding.top + (i / numHorizontalLines) * chartHeight
      const value = maxValue - (i / numHorizontalLines) * valueRange
      
      // Skip drawing the zero line again if we already drew it
      if (zeroY !== null && Math.abs(y - zeroY) < 1) continue
      
      // Grid line
      ctx.beginPath()
      ctx.setLineDash([2, 2])
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.05)'
      ctx.moveTo(padding.left, y)
      ctx.lineTo(padding.left + chartWidth, y)
      ctx.stroke()
      
      // Y-axis label
      ctx.fillStyle = '#94A3B8'
      ctx.font = '11px "Inter", sans-serif'
      ctx.textAlign = 'right'
      ctx.textBaseline = 'middle'
      ctx.fillText(formatNumber(Math.round(value)), padding.left - 12, y)
    }
    
    // Reset line dash
    ctx.setLineDash([])
    
    // Draw X-axis labels
    for (let i = 0; i < days.length; i++) {
      const dayData = days[i]
      if (!dayData) continue
      
      const x = padding.left + (chartWidth / (days.length - 1)) * i
      const isWeekend = dayData.dayName === 'LØR' || dayData.dayName === 'SØN'
      
      // X-axis labels - show day number for all days
      ctx.textAlign = 'center'
      
      // Day number (always show)
      ctx.font = '11px "Inter", sans-serif'
      ctx.fillStyle = isWeekend ? '#64748B' : '#94A3B8'
      ctx.fillText(dayData.dayNumber, x, padding.top + chartHeight + 16)
      
      // Day name (only for some days to reduce clutter)
      if (isWeekend || i % 5 === 0 || i === days.length - 1) {
        ctx.font = '10px "Inter", sans-serif'
        ctx.fillStyle = isWeekend ? '#818CF8' : '#64748B'
        ctx.fillText(dayData.dayName, x, padding.top + chartHeight + 6)
      }
    }
    
    // Create gradient for the area under the line
    const gradient = ctx.createLinearGradient(0, 0, 0, chartHeight + padding.top)
    gradient.addColorStop(0, 'rgba(99, 102, 241, 0.15)')
    gradient.addColorStop(1, 'rgba(99, 102, 241, 0.01)')

    // Draw area under line
    ctx.beginPath()
    // Start at the bottom left (or at the zero line if it's visible)
    const startY = zeroY !== null ? Math.min(padding.top + chartHeight, zeroY) : padding.top + chartHeight
    ctx.moveTo(padding.left, startY)
    
    // Update points state
    setPoints(calculatedPoints)
    
    // Draw the line path for the area
    calculatedPoints.forEach((point, i) => {
      if (i === 0) {
        ctx.moveTo(point.x, point.y)
      } else {
        ctx.lineTo(point.x, point.y)
      }
    })
    
    // Close the path for the area (to the bottom right, then back to the start)
    const endY = zeroY !== null ? Math.min(padding.top + chartHeight, zeroY) : padding.top + chartHeight
    ctx.lineTo(padding.left + chartWidth, endY)
    ctx.closePath()
    ctx.fillStyle = gradient
    ctx.fill()

    // Draw the line
    ctx.beginPath()
    ctx.strokeStyle = '#6366F1' // Indigo-500
    ctx.lineWidth = 3
    ctx.lineCap = 'round'
    ctx.lineJoin = 'round'
    
    // Draw smooth curve through points
    if (calculatedPoints.length > 0) {
      ctx.moveTo(calculatedPoints[0].x, calculatedPoints[0].y)
      
      for (let i = 1; i < calculatedPoints.length - 1; i++) {
        const xc = (calculatedPoints[i].x + calculatedPoints[i + 1].x) / 2
        const yc = (calculatedPoints[i].y + calculatedPoints[i + 1].y) / 2
        ctx.quadraticCurveTo(calculatedPoints[i].x, calculatedPoints[i].y, xc, yc)
      }
      
      // Connect last two points with a straight line
      if (calculatedPoints.length > 1) {
        const last = calculatedPoints.length - 1
        ctx.lineTo(calculatedPoints[last].x, calculatedPoints[last].y)
      }
      
      ctx.stroke()
    }
    
    // Draw data points
    const radius = 4
    calculatedPoints.forEach((point, i) => {
      // Only show points for certain days to reduce clutter
      if (i % 5 === 0 || i === calculatedPoints.length - 1) {
        // Point glow
        ctx.beginPath()
        ctx.arc(point.x, point.y, radius + 4, 0, Math.PI * 2)
        ctx.fillStyle = 'rgba(99, 102, 241, 0.2)'
        ctx.fill()
        
        // Point fill
        ctx.beginPath()
        ctx.arc(point.x, point.y, radius, 0, Math.PI * 2)
        ctx.fillStyle = '#6366F1'
        ctx.fill()
      }
    })
  }, [data, days])
  

  
  // Initial draw and resize handler
  useEffect(() => {
    drawChart()
    
    const handleResize = () => {
      drawChart()
    }
    
    window.addEventListener('resize', handleResize)
    return () => window.removeEventListener('resize', handleResize)
  }, [drawChart])

  return (
    <Box className={classes.chartContainer}>
      <Text className={classes.chartTitle}>{title}</Text>
      <Box ref={containerRef} className={classes.chartWrapper}>
        <canvas 
          ref={canvasRef} 
          className={classes.chart}
        />
      </Box>
    </Box>
  )
}
